package app

// MemoService memoizes squares behind an LRU with capacity 2.
type MemoService struct {
	cache *LRU[int, int]
}

func NewMemoService() *MemoService {
	return &MemoService{cache: NewLRU[int, int](2)}
}

func (m *MemoService) Square(n int) int {
	if v, ok := m.cache.Get(n); ok {
		return v
	}
	v := n * n
	m.cache.Put(n, v)
	return v
}

func (m *MemoService) CacheLen() int { return m.cache.Len() }

