package app

import "testing"

func TestLRUEvictsLeastRecentlyUsed(t *testing.T) {
	c := NewLRU[string, int](2)
	c.Put("a", 1)
	c.Put("b", 2)
	// touch "a" so "b" becomes least-recently-used
	if v, ok := c.Get("a"); !ok || v != 1 {
		t.Fatalf("a missing: %v %v", v, ok)
	}
	c.Put("c", 3) // should evict "b", not "a"
	if _, ok := c.Get("b"); ok {
		t.Fatal("b should have been evicted")
	}
	if v, ok := c.Get("a"); !ok || v != 1 {
		t.Fatal("a should still be present")
	}
	if v, ok := c.Get("c"); !ok || v != 3 {
		t.Fatal("c should be present")
	}
	if c.Len() != 2 {
		t.Fatalf("len=%d want 2", c.Len())
	}
}

func TestMemoServiceUsesCache(t *testing.T) {
	m := NewMemoService()
	if m.Square(3) != 9 || m.Square(4) != 16 {
		t.Fatal("wrong squares")
	}
	if m.CacheLen() != 2 {
		t.Fatalf("cache len=%d want 2", m.CacheLen())
	}
	// a third distinct key must not grow the cache past capacity 2
	m.Square(5)
	if m.CacheLen() != 2 {
		t.Fatalf("cache len=%d want 2 after eviction", m.CacheLen())
	}
}

