package app

type LRU[K comparable, V any] struct {
	items map[K]V
}

func NewLRU[K comparable, V any](capacity int) *LRU[K, V] {
	return &LRU[K, V]{items: make(map[K]V)}
}

func (c *LRU[K, V]) Get(key K) (V, bool) {
	v, ok := c.items[key]
	return v, ok
}

func (c *LRU[K, V]) Put(key K, val V) {
	c.items[key] = val
}

func (c *LRU[K, V]) Len() int { return len(c.items) }

package app

type LRU[K comparable, V any] struct {
	cap   int
	order []K
	items map[K]V
}

func NewLRU[K comparable, V any](capacity int) *LRU[K, V] {
	if capacity < 1 {
		capacity = 1
	}
	return &LRU[K, V]{cap: capacity, items: make(map[K]V)}
}

func (c *LRU[K, V]) Get(key K) (V, bool) {
	v, ok := c.items[key]
	return v, ok
}

func (c *LRU[K, V]) Put(key K, val V) {
	if _, ok := c.items[key]; !ok {
		if len(c.order) >= c.cap {
			evict := c.order[0]
			c.order = c.order[1:]
			delete(c.items, evict)
		}
		c.order = append(c.order, key)
	}
	c.items[key] = val
}

func (c *LRU[K, V]) Len() int { return len(c.items) }
